## 1. COMPREENSÃO DO PROBLEMA

Queremos encontrar o menor custo para viajar entre as estações `A` e `B`. O custo de uma viagem depende de quantas vezes entramos em cada sistema: entrar no sistema `i` custa `Pi`, mas percorrer várias ligações desse sistema sem sair dele não gera cobranças adicionais.

A entrada contém um único caso de teste: `N`, `M`, `K`, os preços dos `K` sistemas, as `M` ligações e, por fim, as estações `A` e `B`. A saída é o menor custo ou `-1` se não houver caminho.

Os limites chegam a `100000` para `N`, `M` e `K`. Como cada preço é no máximo `1000`, usamos `long long` para as distâncias. O enunciado garante `N ≥ 2` e `A ≠ B`; ainda assim, o código também trata o caso de não haver caminho.

## 2. PLANEJAMENTO E DESIGN ALGORÍTMICO

Para cada sistema, suas ligações dividem as estações em componentes conexos. Dentro de um mesmo componente, é possível viajar entre quaisquer duas estações usando apenas aquele sistema, pagando uma única passagem ao entrar.

Representamos cada componente como um nó adicional em um grafo direcionado:

- De uma estação para um componente ao qual ela pertence, há uma aresta de custo igual ao preço do sistema.
- Do componente para cada estação que pertence a ele, há uma aresta de custo zero.

Assim, entrar no componente paga a passagem, enquanto sair dele não custa nada. O menor custo pode então ser encontrado com Dijkstra.

Para construir os componentes sem inicializar um DSU de `N` estações para cada sistema, ordenamos as ligações por sistema e usamos um DSU reinicializado apenas para as estações presentes no grupo atual. Cada ligação gera no máximo quatro arestas direcionadas na representação.

**Complexidade:** `O(M log M + (N + M) log(N + M))` em tempo e `O(N + M)` em memória.

## 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>
#include <limits.h>

typedef struct {
    int u, v, type;
} OriginalEdge;

typedef struct {
    long long distance;
    int node;
} HeapItem;

typedef struct {
    HeapItem *items;
    int size;
} MinHeap;

static int compare_edges(const void *a, const void *b) {
    const OriginalEdge *x = (const OriginalEdge *)a;
    const OriginalEdge *y = (const OriginalEdge *)b;

    if (x->type < y->type) return -1;
    if (x->type > y->type) return 1;
    return 0;
}

static int dsu_find(int parent[], int x) {
    if (parent[x] != x) {
        parent[x] = dsu_find(parent, parent[x]);
    }
    return parent[x];
}

static void dsu_union(int parent[], int size[], int a, int b) {
    int root_a = dsu_find(parent, a);
    int root_b = dsu_find(parent, b);

    if (root_a == root_b) return;

    if (size[root_a] < size[root_b]) {
        int temp = root_a;
        root_a = root_b;
        root_b = temp;
    }

    parent[root_b] = root_a;
    size[root_a] += size[root_b];
}

static void add_arc(
    int from,
    int to,
    int weight,
    int head[],
    int arc_to[],
    int arc_weight[],
    int next_arc[],
    int *arc_count
) {
    int id = (*arc_count)++;
    arc_to[id] = to;
    arc_weight[id] = weight;
    next_arc[id] = head[from];
    head[from] = id;
}

static void heap_push(MinHeap *heap, long long distance, int node) {
    int i = heap->size++;

    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap->items[parent].distance <= distance) break;

        heap->items[i] = heap->items[parent];
        i = parent;
    }

    heap->items[i].distance = distance;
    heap->items[i].node = node;
}

static HeapItem heap_pop(MinHeap *heap) {
    HeapItem result = heap->items[0];
    HeapItem last = heap->items[--heap->size];

    if (heap->size > 0) {
        int i = 0;

        while (1) {
            int left = 2 * i + 1;
            int right = left + 1;
            int smallest = i;

            if (left < heap->size &&
                heap->items[left].distance < heap->items[smallest].distance) {
                smallest = left;
            }

            if (right < heap->size &&
                heap->items[right].distance < heap->items[smallest].distance) {
                smallest = right;
            }

            if (smallest == i) break;

            heap->items[i] = heap->items[smallest];
            i = smallest;
        }

        heap->items[i] = last;
    }

    return result;
}

int main(void) {
    int N, M, K;

    if (scanf("%d %d %d", &N, &M, &K) != 3) {
        return 0;
    }

    int *price = (int *)malloc((K + 1) * sizeof(int));
    for (int i = 1; i <= K; i++) {
        scanf("%d", &price[i]);
    }

    OriginalEdge *edges = (OriginalEdge *)malloc(M * sizeof(OriginalEdge));
    for (int i = 0; i < M; i++) {
        scanf("%d %d %d", &edges[i].u, &edges[i].v, &edges[i].type);
    }

    int A, B;
    scanf("%d %d", &A, &B);

    qsort(edges, M, sizeof(OriginalEdge), compare_edges);

    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *dsu_size = (int *)malloc((N + 1) * sizeof(int));
    int *seen = (int *)calloc(N + 1, sizeof(int));

    int *component_stamp = (int *)calloc(N + 1, sizeof(int));
    int *component_id = (int *)malloc((N + 1) * sizeof(int));

    int max_nodes = N + M;
    int *head = (int *)malloc((max_nodes + 1) * sizeof(int));

    int max_arcs = 4 * M + 5;
    int *arc_to = (int *)malloc(max_arcs * sizeof(int));
    int *arc_weight = (int *)malloc(max_arcs * sizeof(int));
    int *next_arc = (int *)malloc(max_arcs * sizeof(int));

    for (int i = 0; i <= max_nodes; i++) {
        head[i] = -1;
    }

    int component_count = 0;
    int arc_count = 0;
    int group_stamp = 0;

    int i = 0;
    while (i < M) {
        int j = i + 1;
        while (j < M && edges[j].type == edges[i].type) {
            j++;
        }

        group_stamp++;

        /* Inicializa o DSU somente para estações que aparecem no grupo. */
        for (int e = i; e < j; e++) {
            int u = edges[e].u;
            int v = edges[e].v;

            if (seen[u] != group_stamp) {
                seen[u] = group_stamp;
                parent[u] = u;
                dsu_size[u] = 1;
            }
            if (seen[v] != group_stamp) {
                seen[v] = group_stamp;
                parent[v] = v;
                dsu_size[v] = 1;
            }

            dsu_union(parent, dsu_size, u, v);
        }

        /* Cria os nós de componente e as arestas do grafo expandido. */
        for (int e = i; e < j; e++) {
            int u = edges[e].u;
            int v = edges[e].v;
            int root = dsu_find(parent, u);

            if (component_stamp[root] != group_stamp) {
                component_stamp[root] = group_stamp;
                component_id[root] = ++component_count;
            }

            int component_node = N + component_id[root];
            int cost = price[edges[e].type];

            add_arc(u, component_node, cost, head, arc_to,
                    arc_weight, next_arc, &arc_count);
            add_arc(component_node, u, 0, head, arc_to,
                    arc_weight, next_arc, &arc_count);

            add_arc(v, component_node, cost, head, arc_to,
                    arc_weight, next_arc, &arc_count);
            add_arc(component_node, v, 0, head, arc_to,
                    arc_weight, next_arc, &arc_count);
        }

        i = j;
    }

    int total_nodes = N + component_count;
    long long *distance = (long long *)malloc((total_nodes + 1) * sizeof(long long));
    for (int node = 1; node <= total_nodes; node++) {
        distance[node] = LLONG_MAX / 4;
    }

    MinHeap heap;
    heap.items = (HeapItem *)malloc((max_arcs + 5) * sizeof(HeapItem));
    heap.size = 0;

    distance[A] = 0;
    heap_push(&heap, 0, A);

    while (heap.size > 0) {
        HeapItem current = heap_pop(&heap);
        int node = current.node;

        if (current.distance != distance[node]) {
            continue;
        }

        if (node == B) {
            break;
        }

        for (int arc = head[node]; arc != -1; arc = next_arc[arc]) {
            int next_node = arc_to[arc];
            long long new_distance = current.distance + arc_weight[arc];

            if (new_distance < distance[next_node]) {
                distance[next_node] = new_distance;
                heap_push(&heap, new_distance, next_node);
            }
        }
    }

    if (distance[B] == LLONG_MAX / 4) {
        printf("-1\n");
    } else {
        printf("%lld\n", distance[B]);
    }

    free(price);
    free(edges);
    free(parent);
    free(dsu_size);
    free(seen);
    free(component_stamp);
    free(component_id);
    free(head);
    free(arc_to);
    free(arc_weight);
    free(next_arc);
    free(distance);
    free(heap.items);

    return 0;
}
```

## 4. RETROSPECTO E VERIFICAÇÃO

A representação cobra o preço ao sair de uma estação para um componente e cobra zero ao sair do componente para uma estação. Portanto, uma passagem é paga ao entrar no sistema, e as ligações do mesmo componente podem ser usadas sem pagamentos adicionais.

Nos exemplos, o algoritmo encontra custo `11` no primeiro caso, `-1` no segundo e `2` no terceiro. Ligações repetidas dentro do mesmo componente podem gerar arestas duplicadas no grafo expandido, mas isso não altera o resultado de Dijkstra. As distâncias usam `long long`, e as estações ou componentes inalcançáveis são tratados imprimindo `-1`.

